#!/usr/bin/env bash
set -euo pipefail
command -v node >/dev/null 2>&1 || { echo 'Node.js is required; use the terminal where you run npm.' >&2; exit 1; }
node <<'AFACTOR_FREE_DEMO_NODE'
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const files = {"src/app/tutor/page.tsx": "'use client';\nimport { useEffect, useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { lessons } from '@/lib/tutor/lessons';\nimport { demoAnswer, detectIntent, isLanguage, languageName, languages, localizedLesson, strings, type DemoIntent, type Language } from '@/lib/tutor/local-demo';\n\ntype Result = { selected: number; correct: boolean };\ntype Message = { question: string; intent: DemoIntent | null };\nconst STORAGE = 'afactor-stem-tutor-v1';\nconst LANGUAGE_STORAGE = 'afactor-stem-tutor-language-v1';\nconst button = 'rounded-xl border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-800 hover:border-indigo-500 focus-visible:outline-2 focus-visible:outline-indigo-600 disabled:opacity-50';\nconst intents: DemoIntent[] = ['explain', 'example', 'activity', 'hint', 'solution'];\n\nexport default function TutorPage() {\n  const [language, setLanguage] = useState<Language>('en');\n  const [lessonId, setLessonId] = useState(lessons[0].id);\n  const [stage, setStage] = useState<'learn' | 'explore' | 'practise'>('learn');\n  const [results, setResults] = useState<Record<string, Result>>({});\n  const [loaded, setLoaded] = useState(false);\n  const [storageError, setStorageError] = useState(false);\n  const [selected, setSelected] = useState<number | null>(null);\n  const [hint, setHint] = useState(false);\n  const [question, setQuestion] = useState('');\n  const [messages, setMessages] = useState<Message[]>([]);\n  const lesson = localizedLesson(lessonId, language);\n  const ui = strings(language);\n  const result = results[lesson.id];\n  const promptLabels = { explain: ui.explain, example: ui.showExample, activity: ui.showActivity, hint: ui.showHint, solution: ui.showSolution };\n  const subjectName = (subject: typeof lesson.subject) => ui.subjects[subject];\n  useEffect(() => {\n    try {\n      const lang = localStorage.getItem(LANGUAGE_STORAGE);\n      if (isLanguage(lang)) setLanguage(lang);\n      const saved: unknown = JSON.parse(localStorage.getItem(STORAGE) || '{}');\n      const valid: Record<string, Result> = {};\n      if (saved && typeof saved === 'object') for (const l of lessons) {\n        const value = (saved as Record<string, Result>)[l.id];\n        if (value && Number.isInteger(value.selected) && value.selected >= 0 && value.selected < l.options.length)\n          valid[l.id] = { selected: value.selected, correct: value.selected === l.correct };\n      }\n      setResults(valid);\n    } catch { setStorageError(true); }\n    setLoaded(true);\n  }, []);\n  useEffect(() => {\n    if (!loaded) return;\n    try { localStorage.setItem(STORAGE, JSON.stringify(results)); localStorage.setItem(LANGUAGE_STORAGE, language); }\n    catch { setStorageError(true); }\n  }, [results, language, loaded]);\n  function changeLesson(id: string) {\n    setLessonId(id); setStage('learn'); setSelected(null); setHint(false); setMessages([]); setQuestion('');\n  }\n  function addMessage(intent: DemoIntent | null, text: string) {\n    setMessages(m => [...m.slice(-9), { question: text, intent }]);\n  }\n  function ask(event: React.FormEvent) {\n    event.preventDefault();\n    if (!question.trim()) return;\n    addMessage(detectIntent(question), question.trim()); setQuestion('');\n  }\n  function exportProgress() {\n    const lines = [ui.record, languageName(language), ui.saved, ...lessons.map(l => `${subjectName(l.subject)}: ${localizedLesson(l.id, language).title} — ${results[l.id] ? results[l.id].correct ? ui.correct : ui.review : ui.notAttempted}`)];\n    const url = URL.createObjectURL(new Blob([lines.join('\\n')], { type: 'text/plain;charset=utf-8' }));\n    const a = document.createElement('a'); a.href = url; a.download = 'A-Factor_STEM_Practice_Record.txt';\n    document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000);\n  }\n  return <div data-stem-tutor-contrast lang={language} style={{ backgroundColor: '#f1f5f9', color: '#111827', colorScheme: 'light', minHeight: '100vh' }}><AppHeader />\n    <main className=\"mx-auto max-w-6xl px-4 py-8 sm:px-6 sm:py-12\">\n      <div className=\"mb-6 flex flex-wrap items-start justify-between gap-5\">\n        <div className=\"max-w-2xl\"><p className=\"mb-2 text-xs font-semibold uppercase tracking-widest text-indigo-700\">A-Factor STEM Studio</p><h1 className=\"text-3xl font-semibold tracking-tight sm:text-4xl\">{ui.heading}</h1><p className=\"mt-3 text-sm leading-6 text-gray-700\">{ui.intro}</p></div>\n        <div className=\"space-y-3\"><span className=\"inline-block rounded-full bg-emerald-100 px-3 py-2 text-xs font-semibold text-emerald-900\">{ui.badge}</span><label className=\"block text-sm font-medium\" htmlFor=\"tutor-language\">{ui.language}</label><select id=\"tutor-language\" value={language} onChange={e => { if (isLanguage(e.target.value)) setLanguage(e.target.value); }} className=\"w-full rounded-xl border border-gray-300 bg-white px-4 py-3 text-gray-900 focus:outline-indigo-600\">{languages.map(lang => <option key={lang} value={lang}>{languageName(lang)}</option>)}</select></div>\n      </div>\n      <div className=\"mb-6 grid grid-cols-2 gap-2 sm:grid-cols-4\" aria-label={ui.subject}>{lessons.map(l => <button key={l.id} onClick={() => changeLesson(l.id)} aria-pressed={lesson.id === l.id} className={`${button} py-4 ${lesson.id === l.id ? '!border-indigo-600 !bg-indigo-600 !text-white' : ''}`}>{subjectName(l.subject)}</button>)}</div>\n      <div className=\"grid items-start gap-6 lg:grid-cols-[1fr_300px]\">\n        <section className=\"overflow-hidden rounded-2xl border border-gray-200 bg-white\">\n          <div className=\"border-b border-gray-200 p-6\"><p className=\"text-xs font-semibold text-indigo-700\">{subjectName(lesson.subject)}</p><h2 className=\"mt-2 text-2xl font-semibold\">{lesson.title}</h2><p className=\"mt-2 text-sm leading-6 text-gray-700\">{lesson.objective}</p></div>\n          <div className=\"flex flex-wrap gap-2 border-b border-gray-200 px-6 py-3\">{(['learn', 'explore', 'practise'] as const).map((s, i) => <button key={s} onClick={() => setStage(s)} aria-pressed={stage === s} className={`rounded-lg px-3 py-2 text-sm ${stage === s ? 'bg-indigo-100 font-semibold text-indigo-900' : 'text-gray-700 hover:bg-gray-100'}`}>{i + 1}. {ui[s]}</button>)}</div>\n          <div className=\"min-h-80 p-6\">\n            {stage === 'learn' && <><h3 className=\"font-semibold\">{ui.idea}</h3><p className=\"mt-3 text-sm leading-7 text-gray-700\">{lesson.explanation}</p><div className=\"my-6 rounded-xl bg-indigo-50 p-5\"><h3 className=\"text-sm font-semibold text-indigo-900\">{ui.example}</h3><p className=\"mt-2 text-sm leading-7 text-indigo-950\">{lesson.example}</p></div><button className={button} onClick={() => setStage('explore')}>{ui.explore} →</button></>}\n            {stage === 'explore' && <><h3 className=\"font-semibold\">{ui.investigate}</h3><p className=\"my-4 text-sm leading-7 text-gray-700\">{lesson.investigation}</p>{lesson.resource && <Link href={lesson.resource.href} target=\"_blank\" rel=\"noopener noreferrer\" className=\"inline-block rounded-xl bg-indigo-600 px-4 py-3 text-sm font-medium text-white\">{ui.open} ↗</Link>}<p className=\"my-4 text-xs leading-6 text-gray-700\">{lesson.resource ? ui.activityNote : ui.biologyNote}</p><button className={button} onClick={() => setStage('practise')}>{ui.practise} →</button></>}\n            {stage === 'practise' && <><h3 className=\"font-semibold leading-7\">{lesson.question}</h3><fieldset disabled={!!result} className=\"my-4 space-y-2\"><legend className=\"sr-only\">{lesson.question}</legend>{lesson.options.map((option, i) => <label key={i} className={`flex cursor-pointer items-center gap-3 rounded-xl border p-3 text-sm ${((result?.selected ?? selected) === i) ? 'border-indigo-600 bg-indigo-50' : 'border-gray-300'}`}><input type=\"radio\" name={lesson.id} checked={(result?.selected ?? selected) === i} onChange={() => setSelected(i)} />{option}</label>)}</fieldset>\n              {!result ? <div className=\"flex flex-wrap gap-2\"><button className={button} disabled={selected === null || !loaded} onClick={() => { if (selected !== null) setResults(r => ({ ...r, [lesson.id]: { selected, correct: selected === lesson.correct } })); }}>{ui.check}</button><button className={button} onClick={() => setHint(true)}>{ui.hint}</button></div> : <div role=\"status\" className={`rounded-xl p-4 text-sm leading-7 ${result.correct ? 'bg-emerald-50 text-emerald-950' : 'bg-amber-50 text-amber-950'}`}><strong>{result.correct ? ui.correct : ui.review}. </strong>{lesson.solution}<button className=\"mt-3 block underline\" onClick={() => { setResults(r => { const next = { ...r }; delete next[lesson.id]; return next; }); setSelected(null); setHint(false); }}>{ui.retry}</button></div>}\n              {hint && !result && <p role=\"status\" className=\"mt-4 rounded-xl bg-gray-100 p-4 text-sm leading-7\">{lesson.hint}</p>}</>}\n          </div>\n        </section>\n        <aside className=\"rounded-2xl border border-gray-200 bg-white p-5\"><h2 className=\"font-semibold\">{ui.record}</h2><p className=\"my-3 text-sm text-gray-700\">{ui.attempted}: {Object.keys(results).length} / 4 · {ui.correct}: {Object.values(results).filter(r => r.correct).length}</p><ul className=\"space-y-3\">{lessons.map(l => <li key={l.id} className=\"flex justify-between gap-2 text-xs leading-5\"><span>{subjectName(l.subject)}</span><span className={results[l.id]?.correct ? 'text-emerald-800' : 'text-gray-700'}>{results[l.id] ? results[l.id].correct ? ui.correct : ui.review : ui.notAttempted}</span></li>)}</ul><p className=\"mt-4 text-xs leading-6 text-gray-700\">{ui.saved}</p>{storageError && <p role=\"status\" className=\"mt-2 text-xs text-amber-900\">{ui.storageError}</p>}<button className={`${button} mt-4 w-full`} onClick={exportProgress}>{ui.download}</button><button className=\"mt-3 w-full text-xs text-gray-700 underline\" onClick={() => { if (window.confirm(ui.confirm)) { setResults({}); setSelected(null); setHint(false); } }}>{ui.clear}</button></aside>\n      </div>\n      <section className=\"mt-6 rounded-2xl border border-gray-200 bg-white p-6\"><h2 className=\"text-xl font-semibold\">{ui.coach}</h2><p className=\"mt-3 rounded-xl bg-emerald-50 p-4 text-sm leading-7 text-emerald-950\">{ui.demoNotice}</p>\n        <div className=\"my-4 flex flex-wrap gap-2\">{intents.map(intent => <button key={intent} className={button} onClick={() => addMessage(intent, '')}>{promptLabels[intent]}</button>)}</div>\n        <div role=\"log\" aria-live=\"polite\" aria-label={ui.coach} className=\"max-h-96 space-y-3 overflow-y-auto\">{messages.map((m, i) => <div key={i}><div className=\"ml-4 rounded-xl bg-indigo-50 p-3 text-sm leading-7\"><strong>{ui.you}: </strong>{m.question || (m.intent ? promptLabels[m.intent] : '')}</div><div className=\"mr-4 mt-2 whitespace-pre-wrap rounded-xl bg-gray-100 p-4 text-sm leading-7\"><strong className=\"mb-1 block text-xs\">{ui.tutor}</strong>{demoAnswer(lesson.id, language, m.intent)}</div></div>)}</div>\n        <form onSubmit={ask} className=\"mt-4 flex flex-wrap gap-2\"><label htmlFor=\"tutor-question\" className=\"sr-only\">{ui.placeholder}</label><textarea id=\"tutor-question\" value={question} onChange={e => setQuestion(e.target.value)} maxLength={1200} rows={2} placeholder={ui.placeholder} className=\"min-w-0 flex-1 rounded-xl border border-gray-300 bg-white p-3 text-sm text-gray-900 placeholder:text-gray-600 focus:outline-indigo-600\" /><button className={button} disabled={!question.trim()}>{ui.send}</button></form>\n      </section>\n      <p className=\"mt-6 rounded-xl border border-amber-200 bg-amber-50 p-4 text-xs leading-6 text-amber-950\">{ui.translationNote}</p><p className=\"mt-5 text-center text-xs leading-6 text-gray-700\">Mr Dawodu O.F. · A-Factor EdTech Solutions · {ui.limit}</p>\n    </main></div>;\n}\n", "src/lib/tutor/local-demo.ts": "import data from './translation-data.json';\nimport { lessons, type Lesson } from './lessons';\nexport const languages = ['en', 'yo', 'ha', 'ig'] as const;\nexport type Language = typeof languages[number];\nexport type DemoIntent = 'explain' | 'example' | 'activity' | 'hint' | 'solution';\nexport function isLanguage(value: unknown): value is Language { return languages.some(l => l === value); }\nexport function strings(language: Language) { return data[language].ui; }\nexport function languageName(language: Language) { return data[language].name; }\nexport function localizedLesson(id: string, language: Language): Lesson {\n  const base = lessons.find(l => l.id === id) || lessons[0];\n  if (language === 'en') return base;\n  const translations = data[language].lessons;\n  const copy = translations[base.id as keyof typeof translations];\n  return { ...base, ...copy };\n}\nexport function normalize(text: string) {\n  return text.normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase().replace(/[^a-z0-9\\s]/g, ' ').replace(/\\s+/g, ' ').trim();\n}\nconst patterns: [DemoIntent, string[]][] = [\n  ['hint', ['hint', 'clue', 'iṭoniṣona', 'itọnisọna', 'alamar taimako', 'ntuziaka']],\n  ['example', ['example', 'apẹẹrẹ', 'apere', 'misali', 'ihe atụ', 'ihe atu']],\n  ['activity', ['activity', 'simulation', 'investigation', 'experiment', 'ise', 'aiki', 'nnwale', 'oru']],\n  ['solution', ['solution', 'answer', 'idahun', 'ojutu', 'amsa', 'mafita', 'aziza', 'ngwota']],\n  ['explain', ['explain', 'explanation', 'salaye', 'alaye', 'bayyana', 'bayani', 'kowaa', 'nkọwa', 'nkowa']],\n];\n// Whole phrases only: the demo does not pretend to solve unfamiliar questions.\nexport function detectIntent(question: string): DemoIntent | null {\n  const text = ' ' + normalize(question) + ' ';\n  for (const [intent, phrases] of patterns) if (phrases.some(p => text.includes(' ' + normalize(p) + ' '))) return intent;\n  return null;\n}\nexport function demoAnswer(id: string, language: Language, intent: DemoIntent | null): string {\n  const lesson = localizedLesson(id, language);\n  if (intent === 'explain') return lesson.explanation;\n  if (intent === 'example') return lesson.example;\n  if (intent === 'activity') return lesson.investigation;\n  if (intent === 'hint') return lesson.hint;\n  if (intent === 'solution') return lesson.solution;\n  return strings(language).fallback;\n}\n", "src/lib/tutor/translation-data.json": "{\n  \"en\": {\n    \"name\": \"English\",\n    \"ui\": {\n      \"heading\": \"Your STEM study companion\",\n      \"intro\": \"Learn a concept, explore an activity and practise in your preferred language.\",\n      \"badge\": \"Free guided demo · No API key\",\n      \"language\": \"Learning language\",\n      \"subject\": \"Subject\",\n      \"learn\": \"Learn\",\n      \"explore\": \"Explore\",\n      \"practise\": \"Practise\",\n      \"idea\": \"The idea\",\n      \"example\": \"Worked example\",\n      \"investigate\": \"Predict, investigate, explain\",\n      \"open\": \"Open activity\",\n      \"activityNote\": \"The activity opens in a new tab and may be in English. Return here to practise. This tutor cannot see its settings.\",\n      \"biologyNote\": \"Guided thought experiment; no Biology simulation is connected.\",\n      \"check\": \"Check answer\",\n      \"hint\": \"Give me a hint\",\n      \"correct\": \"Correct\",\n      \"review\": \"Needs review\",\n      \"retry\": \"Try again\",\n      \"record\": \"Your practice record\",\n      \"attempted\": \"Attempted\",\n      \"notAttempted\": \"Not attempted\",\n      \"download\": \"Download record\",\n      \"clear\": \"Clear record\",\n      \"confirm\": \"Clear all practice results on this browser?\",\n      \"saved\": \"Saved on this browser only. One question does not establish mastery.\",\n      \"storageError\": \"Browser storage is unavailable. Progress may not persist.\",\n      \"coach\": \"Ask the demo tutor\",\n      \"demoNotice\": \"This tutor selects prepared lesson responses on your device. It is not live generative AI. It does not send your questions to an AI service.\",\n      \"explain\": \"Explain this concept\",\n      \"showExample\": \"Show a worked example\",\n      \"showActivity\": \"Suggest an activity\",\n      \"showHint\": \"Give me a hint\",\n      \"showSolution\": \"Explain the answer\",\n      \"placeholder\": \"Ask for an explanation, example, activity, hint or solution…\",\n      \"send\": \"Ask\",\n      \"you\": \"You\",\n      \"tutor\": \"Demo tutor\",\n      \"fallback\": \"I can explain this selected lesson, show its worked example, suggest its activity, give a hint or explain the practice answer. Choose a suggestion above. I cannot answer arbitrary questions in this free demo.\",\n      \"translationNote\": \"Local-language wording is draft teaching content. Scientific terms are sometimes retained in English; a fluent subject teacher should review it before classroom use.\",\n      \"limit\": \"Four starter lessons, not a complete curriculum.\",\n      \"subjects\": {\n        \"Physics\": \"Physics\",\n        \"Chemistry\": \"Chemistry\",\n        \"Biology\": \"Biology\",\n        \"Mathematics\": \"Mathematics\"\n      }\n    },\n    \"lessons\": {}\n  },\n  \"yo\": {\n    \"name\": \"Yorùbá\",\n    \"ui\": {\n      \"heading\": \"Olùrànlọ́wọ́ ẹ̀kọ́ STEM rẹ\",\n      \"intro\": \"Kọ́ èrò kan, ṣe àyẹ̀wò ìṣe kan, kí o sì dán ìmọ̀ rẹ wò ní èdè tí o fẹ́.\",\n      \"badge\": \"Àpẹẹrẹ ọ̀fẹ́ · Kò nílò API key\",\n      \"language\": \"Èdè ẹ̀kọ́\",\n      \"subject\": \"Kókó ẹ̀kọ́\",\n      \"learn\": \"Kọ́ ẹ̀kọ́\",\n      \"explore\": \"Ṣe àyẹ̀wò\",\n      \"practise\": \"Dán ìmọ̀ wò\",\n      \"idea\": \"Èrò pàtàkì\",\n      \"example\": \"Àpẹẹrẹ pẹ̀lú ojútùú\",\n      \"investigate\": \"Sọ àsọtẹ́lẹ̀, ṣe àyẹ̀wò, ṣàlàyé\",\n      \"open\": \"Ṣí ohun èlò ìṣe\",\n      \"activityNote\": \"Ìṣe yìí yóò ṣí ní táàbù tuntun, ó sì lè wà ní Gẹ̀ẹ́sì. Padà síbí láti dán ìmọ̀ rẹ wò. Olùrànlọ́wọ́ yìí kò lè rí àwọn ètò rẹ.\",\n      \"biologyNote\": \"Àdánwò inú èrò ni èyí; a kò tíì so simulation Biology mọ́ ọn.\",\n      \"check\": \"Ṣàyẹ̀wò ìdáhùn\",\n      \"hint\": \"Fún mi ní ìtọ́nisọ́nà\",\n      \"correct\": \"Ó tọ́\",\n      \"review\": \"Tún un kà\",\n      \"retry\": \"Gbìyànjú lẹ́ẹ̀kan sí i\",\n      \"record\": \"Àkọsílẹ̀ ìdánwò rẹ\",\n      \"attempted\": \"Tí o ti gbìyànjú\",\n      \"notAttempted\": \"O kò tíì gbìyànjú\",\n      \"download\": \"Ṣe ìgbàsílẹ̀ àkọsílẹ̀\",\n      \"clear\": \"Pa àkọsílẹ̀ rẹ́\",\n      \"confirm\": \"Ṣé kí a pa gbogbo àbájáde ìdánwò inú browser yìí rẹ́?\",\n      \"saved\": \"Inú browser yìí nìkan la fi ń pa á mọ́. Ìbéèrè kan kò fi gbogbo ìmọ̀ rẹ hàn.\",\n      \"storageError\": \"Browser kò lè pa àkọsílẹ̀ mọ́ báyìí.\",\n      \"coach\": \"Béèrè lọ́wọ́ olùrànlọ́wọ́ àpẹẹrẹ\",\n      \"demoNotice\": \"Olùrànlọ́wọ́ yìí ń yan ìdáhùn tí a ti kọ sílẹ̀ lórí ẹ̀rọ rẹ. Kì í ṣe AI tó ń dá ìdáhùn tuntun. A kò fi ìbéèrè rẹ ránṣẹ́ sí ilé iṣẹ́ AI.\",\n      \"explain\": \"Ṣàlàyé èrò yìí\",\n      \"showExample\": \"Fi àpẹẹrẹ pẹ̀lú ojútùú hàn\",\n      \"showActivity\": \"Dábàá ìṣe kan\",\n      \"showHint\": \"Fún mi ní ìtọ́nisọ́nà\",\n      \"showSolution\": \"Ṣàlàyé ìdáhùn\",\n      \"placeholder\": \"Béèrè fún àlàyé, àpẹẹrẹ, ìṣe, ìtọ́nisọ́nà tàbí ojútùú…\",\n      \"send\": \"Béèrè\",\n      \"you\": \"Ìwọ\",\n      \"tutor\": \"Olùrànlọ́wọ́ àpẹẹrẹ\",\n      \"fallback\": \"Mo lè ṣàlàyé ẹ̀kọ́ yìí, fi àpẹẹrẹ hàn, dábàá ìṣe, fún ọ ní ìtọ́nisọ́nà tàbí ṣàlàyé ìdáhùn. Yan ọ̀kan nínú àwọn bọ́tìnì lókè. Àpẹẹrẹ ọ̀fẹ́ yìí kò lè dáhùn gbogbo irú ìbéèrè.\",\n      \"translationNote\": \"Àkọ́kọ́ ẹ̀dà ni ìtumọ̀ èdè yìí. A fi àwọn ọ̀rọ̀ sáyẹ́ǹsì kan sílẹ̀ ní Gẹ̀ẹ́sì. Kí olùkọ́ tó mọ èdè náà dáadáa ṣàyẹ̀wò rẹ̀ kí a tó lò ó ní kíláàsì.\",\n      \"limit\": \"Ẹ̀kọ́ mẹ́rin fún ìbẹ̀rẹ̀; kì í ṣe gbogbo syllabus.\",\n      \"subjects\": {\n        \"Physics\": \"Físíìsì (Physics)\",\n        \"Chemistry\": \"Kẹ́místrì (Chemistry)\",\n        \"Biology\": \"Báyọ́lọ́jì (Biology)\",\n        \"Mathematics\": \"Ìṣirò (Mathematics)\"\n      }\n    },\n    \"lessons\": {\n      \"projectiles\": {\n        \"title\": \"Ìṣípò ohun tí a ju (Projectile motion)\",\n        \"objective\": \"Ṣàlàyé bí igun ìfilọ́lẹ̀ ṣe ń yí ìjìnnà petele padà.\",\n        \"explanation\": \"Ohun tí a ju ń rìn ní ọ̀nà petele àti ní ọ̀nà inárọ̀ ní àkókò kan náà. Bí a kò bá ka ìdènà afẹ́fẹ́ sí, velocity petele kì í yí padà; acceleration inárọ̀ sì ń tọ́ sílẹ̀ pẹ̀lú g. Bí ibi ìfilọ́lẹ̀ àti ibi ìbalẹ̀ bá ga bákan náà, R = u² sin(2θ) / g. Ní ipò yìí, igun 45° ló ń fún wa ní ìjìnnà tó pọ̀ jù.\",\n        \"example\": \"Bí u = 20 m/s, θ = 45° àti g = 10 m/s²: R = (20² × sin 90°) / 10 = 40 m. Velocity inárọ̀ ní ìbẹ̀rẹ̀ jẹ́ 20 sin 45° ≈ 14.14 m/s.\",\n        \"investigation\": \"Ṣe àsọtẹ́lẹ̀: ṣé 30° tàbí 60° ni yóò fún wa ní ìjìnnà tó pọ̀ jù? Ṣí simulation, lo speed àti gravity kan náà fún igun méjèèjì. Jẹ́ kí ibi ìfilọ́lẹ̀ àti ibi ìbalẹ̀ ga bákan náà, má sì ka ìdènà afẹ́fẹ́ sí.\",\n        \"question\": \"Bí speed kò bá yí padà, ibi ìfilọ́lẹ̀ àti ibi ìbalẹ̀ sì ga bákan náà láìsí ìdènà afẹ́fẹ́, igun wo ló fún wa ní ìjìnnà tó pọ̀ jù?\",\n        \"options\": [\n          \"30°\",\n          \"45°\",\n          \"60°\",\n          \"90°\"\n        ],\n        \"hint\": \"Ìjìnnà sinmi lórí sin(2θ). Nígbà wo ni iye sine yìí jẹ́ 1?\",\n        \"solution\": \"45° ló tọ́: sin(2 × 45°) = sin 90° = 1. Speed gbọ́dọ̀ jẹ́ kan náà, ibi méjèèjì gbọ́dọ̀ ga bákan náà, kò sì gbọdọ̀ sí ìdènà afẹ́fẹ́.\"\n      },\n      \"compounds\": {\n        \"title\": \"Àwọn element àti compound\",\n        \"objective\": \"Ṣe ìyàtọ̀ láàárín element àti compound, kí o sì túmọ̀ formula kẹ́míkà.\",\n        \"explanation\": \"Element ní àwọn atom tí iye proton wọn jẹ́ kan náà. Compound ní atom láti inú element tó yàtọ̀ tí wọ́n so pọ̀ ní ìpín tó dúró ṣinṣin. Nínú H₂O, ìpín hydrogen sí oxygen jẹ́ 2:1. O₂ ní element kan ṣoṣo; kì í ṣe compound.\",\n        \"example\": \"H₂O ní atom hydrogen méjì àti atom oxygen kan fún molecule kọ̀ọ̀kan. Molar mass rẹ̀ jẹ́ 2(1.008) + 15.999 = 18.015 g/mol ní ìsúnmọ́. NaCl jẹ́ ionic compound; formula rẹ̀ ń fi ìpín hàn, kì í ṣe molecule kan tó dá dúró.\",\n        \"investigation\": \"Ṣí compound builder. Ṣẹ̀dá H₂O, kí o sì fi formula àti molar mass rẹ̀ wé CO₂. Formula tí o bá kó jọ lórí playground kò fi hàn fúnra rẹ̀ pé compound náà lè dúró ṣinṣin tàbí pé ó wà ní tòótọ́.\",\n        \"question\": \"Èwo nínú àwọn formula wọ̀nyí jẹ́ compound?\",\n        \"options\": [\n          \"O₂\",\n          \"Fe\",\n          \"H₂O\",\n          \"N₂\"\n        ],\n        \"hint\": \"Wá formula tí ó ní àmì element méjì tó yàtọ̀.\",\n        \"solution\": \"H₂O ní hydrogen àti oxygen tí a so pọ̀ lọ́nà kẹ́míkà. O₂ àti N₂ ní element kan ṣoṣo; Fe jẹ́ iron.\"\n      },\n      \"photosynthesis\": {\n        \"title\": \"Photosynthesis: bí ewéko ṣe ń ṣe oúnjẹ\",\n        \"objective\": \"Dá àwọn ohun tí photosynthesis nílò, ohun tí ó ń ṣe àti àwọn ohun tó lè dín iyára rẹ̀ kù mọ̀.\",\n        \"explanation\": \"Photosynthesis ń lo agbára ìmọ́lẹ̀ láti ṣe carbohydrate láti carbon dioxide àti omi. Nínú ewéko, ó ń ṣẹlẹ̀ ní chloroplast. Àkótán equation rẹ̀ ni 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂, pẹ̀lú ìmọ́lẹ̀ àti chlorophyll. Ìmọ́lẹ̀, CO₂ àti temperature lè dín iyára rẹ̀ kù.\",\n        \"example\": \"Ewéko kan ní ìmọ́lẹ̀ tó àti temperature tó yẹ, ṣùgbọ́n CO₂ rẹ̀ kéré. Fífi ìmọ́lẹ̀ kún un nìkan lè má ṣe pọ̀ sí iyára iṣẹ́ náà, nítorí CO₂ ni ohun tí kò tó. Fífi CO₂ kún un lè mú iyára pọ̀ sí i títí ohun mìíràn yóò fi di ààlà.\",\n        \"investigation\": \"Àdánwò inú èrò: fi ewéko méjì tó jọra wé ara wọn, ọ̀kan ní CO₂ díẹ̀, èkejì ní CO₂ púpọ̀. Jẹ́ kí ìmọ́lẹ̀, omi àti temperature jẹ́ kan náà. Sọ ohun tí o retí àti ìdí tí a fi gbọdọ̀ darí àwọn ohun wọ̀nyí.\",\n        \"question\": \"Gas wo ló ń pèsè carbon tí ewéko fi ń ṣe carbohydrate ní photosynthesis?\",\n        \"options\": [\n          \"Oxygen\",\n          \"Nitrogen\",\n          \"Carbon dioxide\",\n          \"Hydrogen\"\n        ],\n        \"hint\": \"Wo reactant tí ó ní carbon nínú equation photosynthesis.\",\n        \"solution\": \"Carbon dioxide ló ń pèsè carbon. Photosynthesis ń tú oxygen jáde; ewéko tún ń ṣe respiration.\"\n      },\n      \"trigonometry\": {\n        \"title\": \"Sine àti cosine\",\n        \"objective\": \"So sine àti cosine pọ̀ mọ́ coordinates lórí unit circle.\",\n        \"explanation\": \"Unit circle ní radius 1. Point kan ní igun θ, tí a wọn ní ọ̀nà anticlockwise láti positive x-axis, ní coordinates (cos θ, sin θ). Cosine ń fi coordinate petele hàn, sine sì ń fi coordinate inárọ̀ hàn. Láti Pythagoras, sin²θ + cos²θ = 1.\",\n        \"example\": \"Ní 30°, (cos 30°, sin 30°) = (√3/2, 1/2). Fún velocity 20 m/s ní 30°, apá petele jẹ́ 20 cos 30° ≈ 17.32 m/s, apá inárọ̀ sì jẹ́ 20 sin 30° = 10 m/s.\",\n        \"investigation\": \"Ṣí unit circle explorer. Fi 30°, 90°, 150° àti 270° wé ara wọn. Kọ àmì positive tàbí negative fún sine àti cosine ní quadrant kọ̀ọ̀kan. Ṣàlàyé ìdí tí sin 30° = sin 150°.\",\n        \"question\": \"Kí ni iye sin 30°?\",\n        \"options\": [\n          \"0\",\n          \"1/2\",\n          \"√3/2\",\n          \"1\"\n        ],\n        \"hint\": \"Sine ni y-coordinate lórí unit circle. Ní 30°, coordinate yìí jẹ́ ìdajì radius.\",\n        \"solution\": \"sin 30° = 1/2. cos 30° = √3/2. Degree ni a ń lò fún ìbéèrè yìí.\"\n      }\n    }\n  },\n  \"ha\": {\n    \"name\": \"Hausa\",\n    \"ui\": {\n      \"heading\": \"Abokin taimakonka na koyon STEM\",\n      \"intro\": \"Koyi bayani, binciki aiki, sannan ka gwada fahimtarka a harshen da ka zaɓa.\",\n      \"badge\": \"Samfurin kyauta · Ba ya buƙatar API key\",\n      \"language\": \"Harshen koyo\",\n      \"subject\": \"Fanni\",\n      \"learn\": \"Koyo\",\n      \"explore\": \"Bincike\",\n      \"practise\": \"Gwaji\",\n      \"idea\": \"Muhimmin bayani\",\n      \"example\": \"Misali da mafita\",\n      \"investigate\": \"Yi hasashe, bincika, bayyana\",\n      \"open\": \"Buɗe aikin gwaji\",\n      \"activityNote\": \"Aikin zai buɗe a sabon shafi kuma yana iya kasancewa da Turanci. Ka dawo nan don gwaji. Wannan mataimaki ba ya ganin saitunan aikin.\",\n      \"biologyNote\": \"Wannan gwajin tunani ne; ba a haɗa simulation na Biology ba tukuna.\",\n      \"check\": \"Duba amsa\",\n      \"hint\": \"Ba ni alamar taimako\",\n      \"correct\": \"Daidai\",\n      \"review\": \"Sake dubawa\",\n      \"retry\": \"Sake gwadawa\",\n      \"record\": \"Rikodin gwajinka\",\n      \"attempted\": \"An gwada\",\n      \"notAttempted\": \"Ba a gwada ba\",\n      \"download\": \"Sauke rikodi\",\n      \"clear\": \"Goge rikodi\",\n      \"confirm\": \"A goge duk sakamakon gwaji a wannan burauza?\",\n      \"saved\": \"Ana adanawa a wannan burauza kawai. Tambaya ɗaya ba ta tabbatar da cikakkiyar ƙwarewa ba.\",\n      \"storageError\": \"Burauza ba ta iya adana rikodi yanzu.\",\n      \"coach\": \"Tambayi mataimakin samfurin\",\n      \"demoNotice\": \"Wannan mataimaki yana zaɓar amsoshin darasin da aka riga aka shirya a na’urarka. Ba AI mai samar da sabbin amsoshi ba ne. Ba ya aika tambayoyinka zuwa sabis na AI.\",\n      \"explain\": \"Bayyana wannan darasi\",\n      \"showExample\": \"Nuna misali da mafita\",\n      \"showActivity\": \"Ba da shawarar aiki\",\n      \"showHint\": \"Ba ni alamar taimako\",\n      \"showSolution\": \"Bayyana amsar\",\n      \"placeholder\": \"Nemi bayani, misali, aiki, alamar taimako ko mafita…\",\n      \"send\": \"Tambaya\",\n      \"you\": \"Kai\",\n      \"tutor\": \"Mataimakin samfurin\",\n      \"fallback\": \"Zan iya bayyana wannan darasi, nuna misalinsa, ba da shawarar aiki, ba da alamar taimako ko bayyana amsar gwaji. Zaɓi ɗaya daga maɓallan da ke sama. Wannan samfurin kyauta ba ya amsa kowace irin tambaya.\",\n      \"translationNote\": \"Fassarar nan daftarin koyarwa ce. An bar wasu kalmomin kimiyya da Turanci. Malamin fannin da ya iya harshen ya kamata ya duba ta kafin amfani a aji.\",\n      \"limit\": \"Darussa huɗu na farko; ba cikakken tsarin karatu ba.\",\n      \"subjects\": {\n        \"Physics\": \"Fisiks (Physics)\",\n        \"Chemistry\": \"Kemistri (Chemistry)\",\n        \"Biology\": \"Ilimin halittu (Biology)\",\n        \"Mathematics\": \"Lissafi (Mathematics)\"\n      }\n    },\n    \"lessons\": {\n      \"projectiles\": {\n        \"title\": \"Motsin abin da aka jefa (Projectile motion)\",\n        \"objective\": \"Bayyana yadda kusurwar jefawa ke sauya nisan kwance.\",\n        \"explanation\": \"Abin da aka jefa yana motsi a kwance da kuma a tsaye a lokaci guda. Idan muka yi watsi da juriyar iska, gudun kwance ba ya sauyawa, yayin da acceleration a tsaye yake zuwa ƙasa da g. Idan tsayin farawa da na sauka ɗaya ne, R = u² sin(2θ) / g. A waɗannan sharuɗɗa, 45° tana ba da nisa mafi girma.\",\n        \"example\": \"Idan u = 20 m/s, θ = 45° da g = 10 m/s²: R = (20² × sin 90°) / 10 = 40 m. Gudun farko a tsaye shi ne 20 sin 45° ≈ 14.14 m/s.\",\n        \"investigation\": \"Yi hasashe: 30° ko 60° za ta ba da nisa mafi girma? Buɗe simulation, sa gudun farko da gravity iri ɗaya, sannan ka kwatanta kusurwoyin. Tsayin farawa da na sauka su zama ɗaya, kuma a yi watsi da juriyar iska.\",\n        \"question\": \"Idan gudun farko da tsayin farawa da sauka iri ɗaya ne ba tare da juriyar iska ba, wace kusurwa ce ke ba da nisa mafi girma?\",\n        \"options\": [\n          \"30°\",\n          \"45°\",\n          \"60°\",\n          \"90°\"\n        ],\n        \"hint\": \"Nisa ya dogara da sin(2θ). A wace kusurwa sine ɗin yake zama 1?\",\n        \"solution\": \"45° ce: sin(2 × 45°) = sin 90° = 1. Wannan yana buƙatar gudun farko ɗaya, tsayin farawa da sauka ɗaya, da rashin juriyar iska.\"\n      },\n      \"compounds\": {\n        \"title\": \"Elements da compounds\",\n        \"objective\": \"Bambanta element da compound kuma ka fassara formula na sinadari.\",\n        \"explanation\": \"Element yana ƙunshe da atoms masu adadin proton iri ɗaya. Compound yana ƙunshe da atoms na elements daban-daban da suka haɗu ta chemical bond cikin daidaitaccen rabo. H₂O yana da hydrogen da oxygen a rabo 2:1. O₂ yana da element ɗaya kawai; ba compound ba ne.\",\n        \"example\": \"H₂O yana da atoms biyu na hydrogen da atom ɗaya na oxygen a kowane molecule. Molar mass ɗinsa kusan 2(1.008) + 15.999 = 18.015 g/mol ne. NaCl ionic compound ne; formulansa yana nuna rabo, ba molecule mai zaman kansa ba.\",\n        \"investigation\": \"Buɗe compound builder. Haɗa H₂O ka kwatanta formulansa da molar mass ɗinsa da CO₂. Haɗa formula a playground kaɗai ba ya tabbatar da cewa sinadarin yana da kwanciyar hankali ko yana wanzuwa a zahiri.\",\n        \"question\": \"Wace formula ce ta compound maimakon element?\",\n        \"options\": [\n          \"O₂\",\n          \"Fe\",\n          \"H₂O\",\n          \"N₂\"\n        ],\n        \"hint\": \"Nemi formula mai alamomin elements biyu daban-daban.\",\n        \"solution\": \"H₂O yana da hydrogen da oxygen da suka haɗu ta chemical bond. O₂ da N₂ suna da element ɗaya kowannensu; Fe shi ne iron.\"\n      },\n      \"photosynthesis\": {\n        \"title\": \"Photosynthesis: yadda tsiro ke samar da abinci\",\n        \"objective\": \"Gano abubuwan da photosynthesis yake amfani da su, abin da yake samarwa da abubuwan da ke rage saurin sa.\",\n        \"explanation\": \"Photosynthesis yana amfani da makamashin haske wajen samar da carbohydrates daga carbon dioxide da ruwa. A tsire-tsire yana faruwa a chloroplasts. Taƙaitacciyar equation ita ce 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂, tare da haske da chlorophyll. Ƙarfin haske, yawan CO₂ da zafin jiki na iya iyakance saurin sa.\",\n        \"example\": \"Tsiro yana samun haske mai isa da zafin jiki mai kyau, amma CO₂ ya yi kaɗan. Ƙara haske kaɗai yana iya yin tasiri kaɗan saboda CO₂ ne bai isa ba. Ƙara CO₂ zai iya ƙara sauri har sai wani abu ya zama abin iyakancewa.\",\n        \"investigation\": \"Gwajin tunani: kwatanta tsire-tsire iri ɗaya, ɗaya yana samun CO₂ kaɗan, ɗayan mai yawa. A bar haske, ruwa da zafin jiki iri ɗaya. Yi hasashen sakamako ka bayyana dalilin da ya sa ake sarrafa waɗannan abubuwa.\",\n        \"question\": \"Wane gas ne yake samar da carbon da ake amfani da shi wajen yin carbohydrates a photosynthesis?\",\n        \"options\": [\n          \"Oxygen\",\n          \"Nitrogen\",\n          \"Carbon dioxide\",\n          \"Hydrogen\"\n        ],\n        \"hint\": \"Duba reactant mai carbon a cikin equation na photosynthesis.\",\n        \"solution\": \"Carbon dioxide ne yake samar da carbon. Ana sakin oxygen a photosynthesis; tsire-tsire kuma suna yin respiration.\"\n      },\n      \"trigonometry\": {\n        \"title\": \"Sine da cosine\",\n        \"objective\": \"Haɗa sine da cosine da coordinates a kan unit circle.\",\n        \"explanation\": \"Unit circle yana da radius 1. Matsayi a kusurwar θ da aka auna akasin tafiyar agogo daga positive x-axis yana da coordinates (cos θ, sin θ). Cosine yana ba da coordinate na kwance, sine kuma na tsaye. Daga Pythagoras, sin²θ + cos²θ = 1.\",\n        \"example\": \"A 30°, (cos 30°, sin 30°) = (√3/2, 1/2). Gudun 20 m/s a 30° yana da ɓangaren kwance 20 cos 30° ≈ 17.32 m/s da na tsaye 20 sin 30° = 10 m/s.\",\n        \"investigation\": \"Buɗe unit circle explorer. Kwatanta 30°, 90°, 150° da 270°. Rubuta ko sine da cosine suna positive ko negative a kowanne quadrant. Bayyana dalilin da ya sa sin 30° = sin 150°.\",\n        \"question\": \"Menene sin 30°?\",\n        \"options\": [\n          \"0\",\n          \"1/2\",\n          \"√3/2\",\n          \"1\"\n        ],\n        \"hint\": \"Sine shi ne y-coordinate a unit circle. A 30° wannan coordinate rabin radius ne.\",\n        \"solution\": \"sin 30° = 1/2. cos 30° = √3/2. Wannan tambaya tana amfani da degrees.\"\n      }\n    }\n  },\n  \"ig\": {\n    \"name\": \"Igbo\",\n    \"ui\": {\n      \"heading\": \"Onye enyemaka gị n’ịmụ STEM\",\n      \"intro\": \"Mụta otu echiche, nyochaa ọrụ, ma nwalee nghọta gị n’asụsụ ị họọrọ.\",\n      \"badge\": \"Ihe ngosi efu · Ọ chọghị API key\",\n      \"language\": \"Asụsụ mmụta\",\n      \"subject\": \"Ihe ọmụmụ\",\n      \"learn\": \"Mụta\",\n      \"explore\": \"Nyochaa\",\n      \"practise\": \"Nwalee\",\n      \"idea\": \"Echiche bụ isi\",\n      \"example\": \"Ihe atụ nwere ngwọta\",\n      \"investigate\": \"Buo amụma, nyochaa, kọwaa\",\n      \"open\": \"Mepee ọrụ\",\n      \"activityNote\": \"Ọrụ a ga-emeghe na taabụ ọhụrụ, ọ pụkwara ịdị na Bekee. Lọghachi ebe a ka ị nwalee nghọta gị. Onye enyemaka a anaghị ahụ ntọala simulation ahụ.\",\n      \"biologyNote\": \"Nke a bụ nnwale n’echiche; e jikọbeghị simulation Biology.\",\n      \"check\": \"Lelee azịza\",\n      \"hint\": \"Nye m ntụziaka\",\n      \"correct\": \"Ọ ziri ezi\",\n      \"review\": \"Leghachi anya\",\n      \"retry\": \"Gbalịa ọzọ\",\n      \"record\": \"Ndekọ nnwale gị\",\n      \"attempted\": \"A nwaleela\",\n      \"notAttempted\": \"A nwaleghị\",\n      \"download\": \"Budata ndekọ\",\n      \"clear\": \"Hichapụ ndekọ\",\n      \"confirm\": \"Hichapụ nsonaazụ nnwale niile dị na nchọgharị a?\",\n      \"saved\": \"A na-echekwa ya naanị na nchọgharị a. Otu ajụjụ anaghị egosi nghọta zuru oke.\",\n      \"storageError\": \"Nchọgharị enweghị ike ichekwa ndekọ ugbu a.\",\n      \"coach\": \"Jụọ onye enyemaka ihe ngosi\",\n      \"demoNotice\": \"Onye enyemaka a na-ahọrọ azịza edoziri tupu oge eruo n’elu ngwaọrụ gị. Ọ bụghị AI na-emepụta azịza ọhụrụ. Ọ naghị eziga ajụjụ gị na ọrụ AI.\",\n      \"explain\": \"Kọwaa echiche a\",\n      \"showExample\": \"Gosi ihe atụ nwere ngwọta\",\n      \"showActivity\": \"Tụpụta ọrụ\",\n      \"showHint\": \"Nye m ntụziaka\",\n      \"showSolution\": \"Kọwaa azịza\",\n      \"placeholder\": \"Rịọ nkọwa, ihe atụ, ọrụ, ntụziaka ma ọ bụ ngwọta…\",\n      \"send\": \"Jụọ\",\n      \"you\": \"Gị\",\n      \"tutor\": \"Onye enyemaka ihe ngosi\",\n      \"fallback\": \"Enwere m ike ịkọwa ihe ọmụmụ a, gosi ihe atụ ya, tụpụta ọrụ, nye ntụziaka ma ọ bụ kọwaa azịza nnwale. Họrọ otu bọtịnụ dị n’elu. Ihe ngosi efu a enweghị ike ịza ụdị ajụjụ niile.\",\n      \"translationNote\": \"Nsụgharị ndị a bụ ọdịnaya mmụta a ka na-enyocha. Ụfọdụ okwu sayensị ka dị na Bekee. Onye nkuzi maara asụsụ na ihe ọmụmụ ahụ kwesịrị inyocha ha tupu iji ha n’ụlọ akwụkwọ.\",\n      \"limit\": \"Ihe ọmụmụ anọ maka mmalite; ọ bụghị usoro ọmụmụ zuru oke.\",\n      \"subjects\": {\n        \"Physics\": \"Fiziks (Physics)\",\n        \"Chemistry\": \"Kemistri (Chemistry)\",\n        \"Biology\": \"Ihe gbasara ndụ (Biology)\",\n        \"Mathematics\": \"Mgbakọ na mwepụ (Mathematics)\"\n      }\n    },\n    \"lessons\": {\n      \"projectiles\": {\n        \"title\": \"Mmegharị ihe a tụbara (Projectile motion)\",\n        \"objective\": \"Kọwaa otú nkuku mbido si agbanwe anya ihe na-aga n’ụzọ kwụ ọtọ n’ala.\",\n        \"explanation\": \"Ihe a tụbara na-aga n’ụzọ kwụ ọtọ n’ala na n’ụzọ elu na ala n’otu oge. Ọ bụrụ na anyị eleghara mgbochi ikuku anya, velocity n’ụzọ kwụ ọtọ n’ala anaghị agbanwe; acceleration n’ụzọ elu na ala na-aga ala na g. Mgbe ebe mbido na ebe ọdịda nọ n’otu ịdị elu, R = u² sin(2θ) / g. N’ọnọdụ ndị a, 45° na-enye anya kachasị.\",\n        \"example\": \"Ọ bụrụ na u = 20 m/s, θ = 45° na g = 10 m/s²: R = (20² × sin 90°) / 10 = 40 m. Velocity mbido n’ụzọ elu bụ 20 sin 45° ≈ 14.14 m/s.\",\n        \"investigation\": \"Buo amụma: 30° ka ọ bụ 60° ga-enye anya kachasị? Mepee simulation, jiri otu speed na gravity tụnyere nkuku abụọ ahụ. Mee ka ebe mbido na ebe ọdịda nọrọ n’otu ịdị elu, ma leghara mgbochi ikuku anya.\",\n        \"question\": \"Mgbe speed mbido adịghị agbanwe, ebe mbido na ebe ọdịda nọ n’otu ịdị elu, na mgbochi ikuku adịghị, nkuku ole na-enye anya kachasị?\",\n        \"options\": [\n          \"30°\",\n          \"45°\",\n          \"60°\",\n          \"90°\"\n        ],\n        \"hint\": \"Anya ahụ dabere na sin(2θ). Olee mgbe sine a hà 1?\",\n        \"solution\": \"45° ziri ezi: sin(2 × 45°) = sin 90° = 1. Speed ga-abụ otu, ebe abụọ ahụ ga-anọ n’otu ịdị elu, mgbochi ikuku agaghịkwa adị.\"\n      },\n      \"compounds\": {\n        \"title\": \"Elements na compounds\",\n        \"objective\": \"Kewaa element na compound ma kọwaa formula kemịkal.\",\n        \"explanation\": \"Element nwere atoms ndị ọnụ ọgụgụ proton ha bụ otu. Compound nwere atoms sitere na elements dị iche iche jikọtara site na chemical bonds n’oke a kapịrị ọnụ. H₂O nwere hydrogen na oxygen n’oke 2:1. O₂ nwere naanị otu element; ọ bụghị compound.\",\n        \"example\": \"H₂O nwere atoms hydrogen abụọ na atom oxygen otu n’ime molecule ọ bụla. Molar mass ya bụ ihe dịka 2(1.008) + 15.999 = 18.015 g/mol. NaCl bụ ionic compound; formula ya na-egosi oke ions, ọ bụghị molecule kwụụrụ onwe ya.\",\n        \"investigation\": \"Mepee compound builder. Rụpụta H₂O ma tụnyere formula na molar mass ya na CO₂. Ịchịkọta formula n’ime playground anaghị egosi n’onwe ya na compound ahụ kwụsiri ike ma ọ bụ na ọ dị n’eziokwu.\",\n        \"question\": \"Kedu formula na-anọchi anya compound kama element?\",\n        \"options\": [\n          \"O₂\",\n          \"Fe\",\n          \"H₂O\",\n          \"N₂\"\n        ],\n        \"hint\": \"Chọọ formula nwere akara elements abụọ dị iche iche.\",\n        \"solution\": \"H₂O nwere hydrogen na oxygen jikọtara site na chemical bonds. O₂ na N₂ nwere naanị otu element n’otu n’otu; Fe bụ iron.\"\n      },\n      \"photosynthesis\": {\n        \"title\": \"Photosynthesis: otú osisi si eme nri\",\n        \"objective\": \"Mata ihe photosynthesis chọrọ, ihe ọ na-emepụta na ihe ndị na-egbochi ọsọ ya.\",\n        \"explanation\": \"Photosynthesis na-eji ike ọkụ mee carbohydrates site na carbon dioxide na mmiri. N’osisi, ọ na-eme na chloroplasts. Equation nchịkọta ya bụ 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂, site n’enyemaka ọkụ na chlorophyll. Ike ọkụ, ọnụọgụ CO₂ na temperature nwere ike igbochi ọsọ ya.\",\n        \"example\": \"Otu osisi nwere ọkụ zuru oke na temperature kwesịrị ekwesị, ma CO₂ dị ntakịrị. Ịgbakwunye naanị ọkụ nwere ike ịgbanwe ọsọ ahụ obere n’ihi na CO₂ ezughị. Ịgbakwunye CO₂ nwere ike ime ka ọsọ bawanye ruo mgbe ihe ọzọ ghọrọ ihe na-egbochi ya.\",\n        \"investigation\": \"Nnwale n’echiche: tụnyere osisi abụọ yiri ibe ha, otu nwere CO₂ ntakịrị, nke ọzọ nwere ọtụtụ. Debe ọkụ, mmiri na temperature ka ha bụrụ otu. Buo amụma ihe ga-eme ma kọwaa ihe mere a ga-eji debe ihe ndị ahụ otu.\",\n        \"question\": \"Kedu gas na-enye carbon a na-eji emepụta carbohydrates n’oge photosynthesis?\",\n        \"options\": [\n          \"Oxygen\",\n          \"Nitrogen\",\n          \"Carbon dioxide\",\n          \"Hydrogen\"\n        ],\n        \"hint\": \"Lee reactant nwere carbon n’ime equation photosynthesis.\",\n        \"solution\": \"Carbon dioxide na-enye carbon. Photosynthesis na-ahapụ oxygen; osisi na-emekwa respiration.\"\n      },\n      \"trigonometry\": {\n        \"title\": \"Sine na cosine\",\n        \"objective\": \"Jikọta sine na cosine na coordinates n’elu unit circle.\",\n        \"explanation\": \"Unit circle nwere radius 1. Ebe dị na nkuku θ a tụrụ megide ụzọ elekere si aga, malite na positive x-axis, nwere coordinates (cos θ, sin θ). Cosine bụ coordinate kwụ ọtọ n’ala, sine bụ coordinate elu na ala. Site na Pythagoras, sin²θ + cos²θ = 1.\",\n        \"example\": \"Na 30°, (cos 30°, sin 30°) = (√3/2, 1/2). Velocity 20 m/s na 30° nwere akụkụ kwụ ọtọ n’ala 20 cos 30° ≈ 17.32 m/s, na akụkụ elu 20 sin 30° = 10 m/s.\",\n        \"investigation\": \"Mepee unit circle explorer. Tụnyere 30°, 90°, 150° na 270°. Dee ma sine na cosine bụ positive ma ọ bụ negative na quadrant ọ bụla. Kọwaa ihe mere sin 30° = sin 150°.\",\n        \"question\": \"Gịnị bụ sin 30°?\",\n        \"options\": [\n          \"0\",\n          \"1/2\",\n          \"√3/2\",\n          \"1\"\n        ],\n        \"hint\": \"Sine bụ y-coordinate n’elu unit circle. Na 30°, coordinate a bụ ọkara radius.\",\n        \"solution\": \"sin 30° = 1/2. cos 30° = √3/2. Ajụjụ a na-eji degrees.\"\n      }\n    }\n  }\n}\n", "capstone/FREE_LANGUAGE_DEMO.md": "# Free local-language demo\n\nRun `bash patch-stem-tutor-free-languages.sh` from the existing project's root, then `npm run dev` and open http://localhost:3000/tutor.\n\nUse the language selector at the top: English, Yorùbá, Hausa or Igbo. The selected language controls all four starter lessons, examples, activities, questions, hints, feedback, practice record and demo tutor responses. Language and practice results persist in browser storage when available. Existing practice results use the same IDs and remain usable.\n\nThe demo tutor has five prepared response types: explain, worked example, activity, hint and solution. Suggestion buttons work in every language. The text box recognises a small set of words for these requests; unfamiliar requests get a clear message asking the learner to choose a supported action. It does not solve arbitrary questions or translate arbitrary new content.\n\nNo API key, credits, payment, Redis connection or model download is needed for this demo page. It makes no calls to /api/tutor. The existing live endpoint and other site features remain untouched. Your other simulations may still use their own existing APIs. The three linked activities open separately and their own interface language is unchanged. Biology remains a guided thought experiment.\n\nFor a capstone demonstration, say: “This is the local multilingual guided prototype. It demonstrates the learning flow and prepared lesson responses in four languages. Live generative AI is a separate optional extension.”\n\n## Try this\n\n1. Select Yorùbá, choose Physics, and click the explanation and example buttons.\n2. Switch to Hausa or Igbo: lessons and prepared replies change language immediately.\n3. Choose Chemistry, Biology or Mathematics; try a hint and submit a practice answer.\n4. Reload and check that language and results persist.\n5. Download the practice record in the selected language.\n\nTechnical terms are sometimes intentionally retained in English beside local-language explanations. Translation wording is draft content: have fluent subject teachers review it before classroom use. No claim of professional translation review or measured learning gains is made.\n\n## Files\n\n- src/app/tutor/page.tsx: replaces tutor UI with free multilingual mode and retains the contrast fix.\n- src/lib/tutor/translation-data.json: editable labels and translated content.\n- src/lib/tutor/local-demo.ts: locale selection and deterministic responses.\n- capstone/FREE_LANGUAGE_DEMO.md: this guide.\n\nBackups are created in .stem-tutor-backups before changing existing files. No package.json, environment settings, live endpoint, header or simulation files are modified.\n\n## Checks completed\n\nProduction build and TypeScript checks passed. Automated checks covered all four languages, four subjects, five prepared response types, preservation of correct-answer indices and activity URLs, multilingual request matching and the unsupported-request fallback. Browser interaction and fluent-speaker review remain to be completed. Managed browser preview was unavailable because the preview runner supplied flags unsupported by this project's Next.js dev command.\n"};
if (!fs.existsSync('package.json') || !fs.existsSync('src/app/tutor/page.tsx') || !fs.existsSync('src/lib/tutor/lessons.ts')) {
 console.error('Run from the root of your project after installing the original STEM Tutor patch. No files changed.');process.exit(1);
}
const root = process.cwd();
for (const relative of [...Object.keys(files), '.stem-tutor-backups']) {
 let current = root;
 for (const part of relative.split('/')) {
  current=path.join(current,part);
  if (fs.existsSync(current) && fs.lstatSync(current).isSymbolicLink()) { console.error('Patch stopped: symbolic link at '+relative);process.exit(1); }
 }
 if (fs.existsSync(relative) && !fs.statSync(relative).isFile() && relative !== '.stem-tutor-backups') { console.error('Expected a file at '+relative);process.exit(1); }
}
const changed=Object.keys(files).filter(p=>!fs.existsSync(p)||fs.readFileSync(p,'utf8')!==files[p]);
if (!changed.length) { console.log('Free language demo is already installed. No changes needed.'); process.exit(0); }
fs.mkdirSync('.stem-tutor-backups',{recursive:true});
const backup=fs.mkdtempSync('.stem-tutor-backups/free-languages-');
const originals=new Map();
for (const p of changed) {
 const original=fs.existsSync(p)?fs.readFileSync(p):null;
 originals.set(p,original);
 if (original!==null) { const target=path.join(backup,p);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,original); }
}
fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify(changed.map(file=>({file,existed:originals.get(file)!==null})),null,2));
try {
 for (const p of changed) { fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,files[p],'utf8'); }
} catch(error) {
 for (const [p,original] of originals) { if(original===null) {if(fs.existsSync(p))fs.unlinkSync(p);}else fs.writeFileSync(p,original); }
 console.error('Patch failed; originals restored: '+error.message);process.exit(1);
}
console.log('Installed: free English, Yorùbá, Hausa and Igbo lessons and prepared demo responses.');
console.log('No API key, payment or Redis setup required for the tutor demo.');
